def first_big(prices, limit):
    found = None
    for p in prices:
        if p > limit:
            found = p
            break
    return found

project.solution:
def grade_all(marks):
    results = []
    for m in marks:
        if m < 0:
            continue
        if m >= 75:
            results.append("Distinction")
        elif m >= 35:
            results.append("Pass")
        else:
            results.append("Try again")
    return results
